        )

    def test_keys_are_isolated(self) -> None:
        self.post_operation("r1", "op-1", "a", "va", {"r1": 1})
        self.post_operation("r1", "op-2", "b", "vb", {"r1": 2})
        _, state_a = self.request("GET", "/v1/states/a")
        _, state_b = self.request("GET", "/v1/states/b")
